def strokes(g,v):
    # find runs of color v in output grouped contiguously (4-conn), return sorted list
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for y in range(H):
        for x in range(W):
            if g[y][x]==v and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); cs=[]
                while st:
                    p=st.pop(); cs.append(p)
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(p[0]+dy,p[1]+dx)
                        if 0<=q[0]<H and 0<=q[1]<W and g[q[0]][q[1]]==v and q not in seen:
                            seen.add(q); st.append(q)
                ys=[c[0] for c in cs]; xs=[c[1] for c in cs]
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                res.append({'n':len(cs),'h':h,'w':w,
                            'top':min(ys),'left':min(xs),'bottom':max(ys),'right':max(xs),
                            'shape':'V' if h>1 and w==1 else ('H' if w>1 and h==1 else '?')})
    return res
